// Cloud Function skeleton for Pub/Sub message validation
exports.validateEvent = (message, context) => {
  const data = JSON.parse(Buffer.from(message.data, 'base64').toString());
  if (!data.ingest_ts || !data.user_id || !data.event_type) {
    // route to GCS errors
    return; 
  }
  // write to BigQuery CLEAN table (pseudo)
};
```

